    auditLog: AuditLogEntry;
    encryptionKey: string;
    encryption_succeeded?: boolean;
    data_isolation_executed?: boolean;
    isolated_storage_location?: string;
    original_location_accessible?: boolean;
    processing_continued?: boolean;
    error_message?: string;
    system_safe_state?: boolean;
    other_operations_available?: boolean;
