/* AIVIC_FUNCTION_BUNDLE_START owner=assignExternalDataTrustScore exports=assignExternalDataTrustScore */
const __aivicBundle_11_assignExternalDataTrustScore = (() => {
  function assignExternalDataTrustScore(externalData: {
    data_source_id: string;
    timestamp?: string;
    data_type: string;
    data_quality_score?: number;
    last_update_timestamp?: string;
    source_reliability_rating?: number;
    [key: string]: unknown;
  }): {
    trust_score: number;
    has_warnings: boolean;
    warning_details: string[];
    processing_status: string;
  } {
    // Validate required identity fields
    if (!String(externalData.data_source_id).trim()) {
      throw new Error('data_source_id is required');
    }
    if (!String(externalData.data_type).trim()) {
      throw new Error('data_type is required');
    }
  
    const warningDetails: string[] = [];
    const missingFields: string[] = [];
  
    // Check for missing optional metadata fields
    if (externalData.data_quality_score === undefined) {
      missingFields.push('data_quality_score');
      warningDetails.push('【data_quality_score】required metadata field missing');
    }
  
    if (externalData.last_update_timestamp === undefined) {
      missingFields.push('last_update_timestamp');
      warningDetails.push('【last_update_timestamp】required metadata field missing');
    }
  
    if (externalData.source_reliability_rating === undefined) {
      missingFields.push('source_reliability_rating');
      warningDetails.push('【source_reliability_rating】required metadata field missing');
    }
  
    if (externalData.timestamp === undefined) {
      missingFields.push('timestamp');
      warningDetails.push('【timestamp】required metadata field missing');
    }
  
    let trustScore: number;
    let hasWarnings: boolean;
    let processingStatus: string;
  
    // If any required metadata is missing, use default score and mark warnings
    if (missingFields.length > 0) {
      trustScore = 0.5;
      hasWarnings = true;
      processingStatus = 'continued_with_default';
  
      // Log warnings to console
      missingFields.forEach((field) => {
        console.warn(`メタデータ欠落: ${field}`);
      });
    } else {
      // All required metadata present: calculate trust score
      const dataQualityScore = externalData.data_quality_score as number;
      const sourceReliabilityRating = externalData.source_reliability_rating as number;
  
      trustScore = (dataQualityScore + sourceReliabilityRating) / 2;
      hasWarnings = false;
      processingStatus = 'success';
    }
  
    return {
      trust_score: trustScore,
      has_warnings: hasWarnings,
      warning_details: warningDetails,
      processing_status: processingStatus,
    };
  }
  return { assignExternalDataTrustScore };
})();
export const assignExternalDataTrustScore = __aivicBundle_11_assignExternalDataTrustScore.assignExternalDataTrustScore;
/* AIVIC_FUNCTION_BUNDLE_END owner=assignExternalDataTrustScore */

