const __aivicBundle_14_determinePriority = (() => {
  function determinePriority(improvement: {
    variable_name: string;
    impact_score: number;
    implementation_difficulty: number;
    correlation_coefficient: number;
    precision_improvement_rate: number;
  }): { priority_level: 'HIGH' | 'MEDIUM' | 'LOW'; priority_score: number } {
    const {
      variable_name,
      impact_score,
      implementation_difficulty,
      correlation_coefficient,
      precision_improvement_rate,
    } = improvement;
  
    // Validate required inputs
    if (!variable_name || String(variable_name).trim() === '') {
      throw new Error('variable_name is required');
    }
    if (correlation_coefficient === undefined || correlation_coefficient === null) {
      throw new Error('correlation_coefficient is required');
    }
    if (precision_improvement_rate === undefined || precision_improvement_rate === null) {
      throw new Error('precision_improvement_rate is required');
    }
  
    // 優先度スコアを計算: 影響度を重視（70%）、実装難度を逆転（30%）
    // 実装難度は低いほど優先度が高いため、(10 - difficulty) で逆転
    const priority_score = (impact_score * 0.7) + ((10 - implementation_difficulty) * 0.3);
  
    // 優先度レベルを判定: 影響度と実装難度の2軸マトリクス
    // 高影響度: impact_score >= 5.0
    // 低難易度: implementation_difficulty < 3.0
    // 中難易度: 3.0 <= implementation_difficulty < 6.0
    // 高難易度: implementation_difficulty >= 6.0
  
    let priority_level: 'HIGH' | 'MEDIUM' | 'LOW';
  
    const isHighImpact = impact_score >= 5.0;
    const isLowDifficulty = implementation_difficulty < 3.0;
    const isMediumDifficulty = implementation_difficulty >= 3.0 && implementation_difficulty < 6.0;
  
    if (isHighImpact && isLowDifficulty) {
      // 高影響度 × 低難易度 = 最優先
      priority_level = 'HIGH';
    } else if (isHighImpact && isMediumDifficulty) {
      // 高影響度 × 中難易度 = 中優先
      priority_level = 'MEDIUM';
    } else if (!isHighImpact && isLowDifficulty) {
      // 低影響度 × 低難易度 = 中優先
      priority_level = 'MEDIUM';
    } else {
      // その他（低影響度 × 中難易度以上、または高難易度）= 低優先
      priority_level = 'LOW';
    }
  
    return {
      priority_level,
      priority_score,
    };
  }
  return { determinePriority };
})();
export const determinePriority = __aivicBundle_14_determinePriority.determinePriority;
/* AIVIC_FUNCTION_BUNDLE_END owner=determinePriority */

