/* AIVIC_FUNCTION_BUNDLE_START owner=validatePriorityMatrixImpact exports=validatePriorityMatrixImpact */
const __aivicBundle_18_validatePriorityMatrixImpact = (() => {
  interface ValidatePriorityMatrixImpactParams {
    impact: number;
    implementationDifficulty: number;
    externalFactorName: string;
  }
  
  interface ValidatePriorityMatrixImpactResult {
    isValid: boolean;
    impact: number;
    implementationDifficulty: number;
    externalFactorName: string;
    priorityQuadrant: string;
  }
  
   function validatePriorityMatrixImpact(
    params: ValidatePriorityMatrixImpactParams
  ): ValidatePriorityMatrixImpactResult {
    const { impact, implementationDifficulty, externalFactorName } = params;
  
    // Validate impact is a number
    if (typeof impact !== 'number' || isNaN(impact)) {
      throw new Error('影響度は有効な数値である必要があります');
    }
  
    // Validate impact is within valid range [0, 100]
    if (impact < 0 || impact > 100) {
      throw new Error('影響度は0から100の範囲内である必要があります');
    }
  
    // Determine priority quadrant based on impact and implementation difficulty
    let priorityQuadrant: string;
  
    if (impact <= 33) {
      priorityQuadrant = 'low_priority';
    } else if (impact <= 66) {
      priorityQuadrant = 'medium_priority';
    } else {
      priorityQuadrant = 'high_priority';
    }
  
    return {
      isValid: true,
      impact,
      implementationDifficulty,
      externalFactorName,
      priorityQuadrant
    };
  }
  return { validatePriorityMatrixImpact };
})();
export const validatePriorityMatrixImpact = __aivicBundle_18_validatePriorityMatrixImpact.validatePriorityMatrixImpact;
