/* AIVIC_FUNCTION_BUNDLE_START owner=describePriorityMatrixPlacementForExternalFactorVariable exports=describePriorityMatrixPlacementForExternalFactorVariable */
const __aivicBundle_19_describePriorityMatrixPlacementForExternalFactorVariable = (() => {
  function describePriorityMatrixPlacementForExternalFactorVariable(params: {
    externalFactorVariable: {
      variableId: string;
      variableName: string;
      impactScore: number;
      implementationDifficulty: number;
    };
    matrixConfig: {
      maxImpactScore: number;
      maxImplementationDifficulty: number;
      quadrantMidpoint: number;
    };
  }): {
    matrixCoordinate: { impactAxis: number; difficultyAxis: number };
    quadrantClassification: string;
    priorityLevel: number;
  } {
    const { externalFactorVariable, matrixConfig } = params;
    const { impactScore, implementationDifficulty } = externalFactorVariable;
    const { maxImpactScore, maxImplementationDifficulty, quadrantMidpoint } = matrixConfig;
  
    // マトリクス座標を設定（スケール値をそのまま使用）
    const matrixCoordinate = {
      impactAxis: impactScore,
      difficultyAxis: implementationDifficulty,
    };
  
    // 象限分類ロジック
    // 影響度と実装難度が両方ともスケール最大値の場合は低優先度象限に分類
    let quadrantClassification: string;
    let priorityLevel: number;
  
    const isMaxImpact = impactScore === maxImpactScore;
    const isMaxDifficulty = implementationDifficulty === maxImplementationDifficulty;
  
    if (isMaxImpact && isMaxDifficulty) {
      // 右上象限：高難度・高影響度 → 低優先度
      quadrantClassification = 'low_priority';
      priorityLevel = quadrantMidpoint - 1;
    } else if (impactScore >= quadrantMidpoint && implementationDifficulty >= quadrantMidpoint) {
      // 右上象限（最大値未満）：高難度・高影響度 → 低優先度
      quadrantClassification = 'low_priority';
      priorityLevel = quadrantMidpoint - 1;
    } else if (impactScore >= quadrantMidpoint && implementationDifficulty < quadrantMidpoint) {
      // 右下象限：低難度・高影響度 → 高優先度
      quadrantClassification = 'high_priority';
      priorityLevel = quadrantMidpoint + 1;
    } else if (impactScore < quadrantMidpoint && implementationDifficulty >= quadrantMidpoint) {
      // 左上象限：高難度・低影響度 → 中優先度
      quadrantClassification = 'medium_priority';
      priorityLevel = quadrantMidpoint;
    } else {
      // 左下象限：低難度・低影響度 → 中優先度
      quadrantClassification = 'medium_priority';
      priorityLevel = quadrantMidpoint;
    }
  
    return {
      matrixCoordinate,
      quadrantClassification,
      priorityLevel,
    };
  }
  return { describePriorityMatrixPlacementForExternalFactorVariable };
})();
export const describePriorityMatrixPlacementForExternalFactorVariable = __aivicBundle_19_describePriorityMatrixPlacementForExternalFactorVariable.describePriorityMatrixPlacementForExternalFactorVariable;
/* AIVIC_FUNCTION_BUNDLE_END owner=describePriorityMatrixPlacementForExternalFactorVariable */

