const __aivicBundle_20_calculateComprehensivePriorityScore = (() => {
  function calculateComprehensivePriorityScore(params: {
    impact_score: number;
    implementation_feasibility_score: number;
  }): number {
    const impactWeight = 0.6;
    const feasibilityWeight = 0.4;
    
    const comprehensiveScore =
      params.impact_score * impactWeight +
      params.implementation_feasibility_score * feasibilityWeight;
    
    return comprehensiveScore;
  }
  return { calculateComprehensivePriorityScore };
})();
