/* AIVIC_FUNCTION_BUNDLE_START owner=generateImprovementProposalWithFactorScoring exports=generateImprovementProposalWithFactorScoring */
const __aivicBundle_21_generateImprovementProposalWithFactorScoring = (() => {
  function generateImprovementProposalWithFactorScoring(params: {
    proposal_id: string;
    factors: Array<{
      factor_id: string;
      factor_name: string;
      impact_score: number;
      implementation_difficulty: number;
      data_quality_score: number;
    }>;
    generated_date: Date;
  }): {
    proposal_id: string;
    generated_date: Date;
    scored_factors: ScoredFactor[];
    status: string;
  } {
    const scoredFactorsWithPriority = params.factors.map((factor) => {
      const priorityScore =
        factor.impact_score * 0.5 +
        (100 - factor.implementation_difficulty) * 0.3 +
        factor.data_quality_score * 0.2;
  
      return {
        factor_id: factor.factor_id,
        factor_name: factor.factor_name,
        priority_score: priorityScore,
        impact_score: factor.impact_score,
        implementation_difficulty_score: factor.implementation_difficulty,
      };
    });
  
    const sortedFactors = scoredFactorsWithPriority.sort(
      (a, b) => b.priority_score - a.priority_score
    );
  
    const scoredFactorsWithRank: ScoredFactor[] = sortedFactors.map(
      (factor, index) => ({
        factor_id: factor.factor_id,
        factor_name: factor.factor_name,
        priority_score: factor.priority_score,
        impact_score: factor.impact_score,
        implementation_difficulty_score: factor.implementation_difficulty_score,
        priority_rank: index + 1,
      })
    );
  
    return {
      proposal_id: params.proposal_id,
      generated_date: params.generated_date,
      scored_factors: scoredFactorsWithRank,
      status: 'generated',
    };
  }
  return { generateImprovementProposalWithFactorScoring };
})();
