const __aivicBundle_22_validateFactorScores = (() => {
  function validateFactorScores(input: {
    factors: Array<{ id: string; name: string; score: unknown }>;
  }): { isValid: boolean; factors: Array<{ id: string; name: string; score: number }> } {
    if (!input || !Array.isArray(input.factors)) {
      throw new Error("スコアの検証に失敗しました");
    }
  
    for (const factor of input.factors) {
      if (
        factor.score === null ||
        factor.score === undefined ||
        typeof factor.score !== "number" ||
        Number.isNaN(factor.score)
      ) {
        throw new Error("スコアは数値である必要があります");
      }
    }
  
    return {
      isValid: true,
      factors: input.factors as Array<{ id: string; name: string; score: number }>,
    };
  }
  return { validateFactorScores };
})();
